 a,b=rows[t-1],rows[t]
 diff=[k for k,(x,y) in enumerate(zip(a,b)) if x!=y]
 if len(diff)!=1: print('bad',t,diff)
 else: changes.append((t,diff[0],b[diff[0]]-a[diff[0]]))
