from collections import defaultdict


def collatz_count(n: int) -> int:
    """统计 Collatz 序列到达 1 时的项数，包含起点和终点。"""
    count = 1

    while n != 1:
        if n % 2:
            n = 3 * n + 1
        else:
            n //= 2

        count += 1

    return count


def bucket_key(n: int) -> int:
    """计算参考答案中的 round(n)，即 Collatz 长度的递归变换。"""
    r = collatz_count(n)

    for _ in range(r - 1):
        r = collatz_count(r)

    return r


def calc(n: int) -> list[int]:
    """生成第 n 行的数据。"""
    if n < 1:
        raise ValueError("n must be a positive integer")

    buckets = defaultdict(list)

    # 根据 Collatz 递归键对 1...n 分组
    for m in range(1, n + 1):
        key = bucket_key(m)
        buckets[key].append(m)

    # 构造稠密数组
    max_key = max(buckets)
    values = [0] * (max_key + 1)

    for key, members in buckets.items():
        count = len(members)
        total = sum(members)

        z = count + total
        values[key] = z * (z + 1) // 2 + total

    # 将连续零压缩成负的长度
    result = []
    i = 0

    while i < len(values):
        if values[i] != 0:
            result.append(values[i])
            i += 1
            continue

        start = i

        while i < len(values) and values[i] == 0:
            i += 1

        result.append(-(i - start))

    return result


if __name__ == "__main__":
    for n in range(1, 501):
        print(f"[{n}]{calc(n)}")

